import { patients } from './data.js';
const app = document.querySelector('#app');
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const date = s => new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(s+'T00:00:00Z'));
const badge = s => `<span class="badge ${s==='Denied'||s==='Claim Denied'?'red':'green'}"><span>●</span> ${s}</span>`;
const crumb = html => `<nav class="breadcrumbs"><a href="#/">Patients</a>${html}</nav>`;
function list(){return `<div class="eyebrow">OVERVIEW</div><div class="page-head"><div><h1>Patients</h1><p>Review benefits and claims for your patients.</p></div><span class="count">${patients.length} patients</span></div><section class="panel"><div class="section-head"><div><h2>Patient directory</h2><p>Select a patient to view their benefits and EOBs.</p></div></div><div class="table-wrap"><table><thead><tr><th>PATIENT</th><th>DATE OF BIRTH</th><th>INSURANCE PAYER</th><th>STATUS</th><th></th></tr></thead><tbody>${patients.map(p=>`<tr><td><a class="patient-link" href="#/patients/${p.id}"><span class="avatar">${p.name.split(' ').map(x=>x[0]).join('')}</span><span>${p.name}<small>Patient #${String(p.id).padStart(3,'0')}</small></span></a></td><td>${date(p.dob)}</td><td>${p.payer}</td><td>${badge(p.status)}</td><td><a class="arrow" href="#/patients/${p.id}" aria-label="View ${p.name}">↗</a></td></tr>`).join('')}</tbody></table></div></section><p class="helper"><span>ⓘ</span> This dashboard displays sample information for demonstration purposes.</p>`}
function detail(p){let b=p.benefits;return `${crumb(` <span>/</span> <strong>${p.name}</strong>`)}<div class="page-head"><div><div class="eyebrow">PATIENT PROFILE</div><h1>${p.name}</h1><p>Benefits and claim activity at a glance.</p></div>${badge(p.status)}</div><section class="panel patient-info"><div><span class="label">DATE OF BIRTH</span><strong>${date(p.dob)}</strong></div><div><span class="label">INSURANCE PAYER</span><strong>${p.payer}</strong></div><div><span class="label">PATIENT ID</span><strong>#${String(p.id).padStart(3,'0')}</strong></div></section><div class="section-title"><div><div class="eyebrow">COVERAGE</div><h2>Benefits summary</h2></div><span>Plan details</span></div><section class="benefit-grid"><div class="panel metric"><span>Annual maximum</span><strong>${money(b.annualMax)}</strong><small>Plan year allowance</small></div><div class="panel metric"><span>Remaining maximum</span><strong>${money(b.remainingMax)}</strong><small>Available benefit</small></div><div class="panel metric"><span>Deductible</span><strong>${money(b.deductible)}</strong><small>Plan year deductible</small></div><div class="panel metric"><span>Deductible remaining</span><strong>${money(b.deductibleRemaining)}</strong><small>Left to meet</small></div></section><section class="panel coverage"><div class="coverage-title">Coverage by service <span>Plan percentage</span></div><div class="coverage-grid">${[['Preventive',b.preventive],['Basic',b.basic],['Major',b.major],['Orthodontic',b.ortho]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div></section><div class="section-title eob-title"><div><div class="eyebrow">CLAIMS</div><h2>Explanation of benefits</h2></div><span>${p.eobs.length} EOB${p.eobs.length===1?'':'s'}</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>DATE</th><th>PROCEDURE</th><th>BILLED</th><th>ALLOWED</th><th>INSURANCE PAID</th><th>PATIENT RESPONSIBILITY</th><th>STATUS</th><th></th></tr></thead><tbody>${p.eobs.map(e=>`<tr><td>${date(e.date)}</td><td><a class="text-link" href="#/patients/${p.id}/eobs/${e.id}">${e.procedure}</a><small>${e.code}</small></td><td>${money(e.billed)}</td><td>${money(e.allowed)}</td><td>${money(e.paid)}</td><td>${money(e.patient)}</td><td>${badge(e.status)}</td><td><a class="arrow" href="#/patients/${p.id}/eobs/${e.id}" aria-label="Analyze ${e.procedure} EOB">↗</a></td></tr>`).join('')}</tbody></table></div></section>`}
function analysis(p,e){return `${crumb(` <span>/</span> <a href="#/patients/${p.id}">${p.name}</a> <span>/</span> <strong>EOB analysis</strong>`)}<div class="page-head"><div><div class="eyebrow">CLAIM DETAILS</div><h1>EOB analysis</h1><p>${p.name} <span class="dot">·</span> ${date(e.date)} <span class="dot">·</span> ${p.payer}</p></div>${badge(e.status)}</div><section class="panel procedure"><div><span class="label">PROCEDURE</span><h2>${e.procedure}</h2><p>Procedure code ${e.code}</p></div><span class="procedure-icon">✚</span></section><div class="analysis-layout"><section class="panel breakdown"><div class="section-head"><div><h2>Financial breakdown</h2><p>Amounts reported on this EOB</p></div></div>${[['Billed amount',e.billed],['Allowed amount',e.allowed],['Insurance paid',e.paid],['Patient responsibility',e.patient]].map(([k,v],i)=>`<div class="break-row ${i===3?'total':''}"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}<p class="footnote">Amounts shown are from the sample EOB. Patient responsibility may change after claim review.</p></section><section class="panel insights"><div class="section-head"><div><h2>Claim analysis</h2><p>Reason, potential issue, and next step</p></div></div><div class="insight"><span class="insight-icon">↳</span><div><span class="label">REASON FOR PAYMENT / ADJUSTMENT</span><p>${e.analysis.reason}</p></div></div><div class="insight"><span class="insight-icon amber">!</span><div><span class="label">POTENTIAL ISSUE</span><p>${e.analysis.issue}</p></div></div><div class="insight"><span class="insight-icon teal">→</span><div><span class="label">SUGGESTED NEXT STEP</span><p>${e.analysis.suggestion}</p></div></div></section></div><a class="back" href="#/patients/${p.id}">← Back to patient profile</a>`}
function render(){const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(!parts.length){app.innerHTML=list();return}const p=parts[0]==='patients'&&patients.find(x=>String(x.id)===parts[1]);if(p&&parts.length===2){app.innerHTML=detail(p);return}const e=p&&parts[2]==='eobs'&&p.eobs.find(x=>x.id===parts[3]);if(e&&parts.length===4){app.innerHTML=analysis(p,e);return}app.innerHTML=`${crumb('')}<h1>Page not found</h1><p>We couldn’t find that patient or EOB.</p><a class="back" href="#/">← Return to patients</a>`}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
